/**
 * The error the SDK's foreign implementations answer with.
 */
public enum SdkError {

    
    
    /**
     * The network refused.
     */
    case NetworkRefused
    /**
     * The transport failed.
     */
    case Transport(String
    )
    /**
     * The host declined.
     */
    case Declined
    /**
     * The host cannot answer.
     */
    case Cannot(String
    )
    /**
     * An internal error.
     */
    case Internal
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSdkError: FfiConverterRustBuffer {
    typealias SwiftType = SdkError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SdkError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NetworkRefused
        case 2: return .Transport(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .Declined
        case 4: return .Cannot(
            try FfiConverterString.read(from: &buf)
            )
        case 5: return .Internal

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SdkError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NetworkRefused:
            writeInt(&buf, Int32(1))
        
        
        case let .Transport(v1):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .Declined:
            writeInt(&buf, Int32(3))
        
        
        case let .Cannot(v1):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .Internal:
            writeInt(&buf, Int32(5))
        
        }
    }
}


extension SdkError: Equatable, Hashable {}

extension SdkError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}




/**
 * The wallet host: the sub-flows the engine asks the wallet's user for.
 * The Kotlin/Swift implementation is the adapter's
 * `engine_ports::Host`.
 */
public protocol Host : AnyObject {
    
    /**
     * Asks the host to sign the given input.
     */
    func requestSign(params: SignParams) async throws  -> SignResult
    
    /**
     * Asks the host to match the wallet's credentials against the DCQL
     * query and select what to present. An empty answer means nothing
     * matched: the flow ends there.
     */
    func requestMatch(params: MatchParams) async throws  -> MatchResult
    
    /**
     * Asks the host to construct and sign the VP token for the
     * selected credentials — the wallet's presentation formats and
     * key custody live in the host.
     */
    func requestVp(params: VpParams) async throws  -> VpResult
    
    /**
     * Asks the host for a client-held DPoP proof; the engine falls
     * back to its own key when the host cannot answer.
     */
    func requestDpopProof(params: DpopProofParams) async throws  -> DpopProofResult
    
    /**
     * Asks the host's user for consent.
     */
    func requestConsent(params: ConsentParams) async throws  -> ConsentResult
    
    /**
     * Asks the host's user for the transaction code.
     */
    func requestTxCode(flowId: String) async throws  -> String
    
    /**
     * Opens the authorization URL in the host's browser.
     */
    func openAuthorization(flowId: String, url: String) async throws 
    
    /**
     * Asks the host for the public JWK of a named signing key, so the
     * engine can identify the key in the proof headers it builds. Keys
     * always live in the app; the engine only ever sees the public
     * JWK. A refusal keeps the flows working without key identification.
     */
    func requestSigningKey(params: SigningKeyParams) async throws  -> SigningKeyResult
    
    /**
     * Asks the host for a client attestation (a Wallet Instance
     * Attestation and its proof of possession), when the AS demands
     * one. A refusal continues without client attestation.
     */
    func requestAttestation(params: AttestationParams) async throws  -> AttestationResult
    
    /**
     * Asks the host's user to pick one of the offered credential
     * configurations, when the offer names more than one. A refusal
     * fails the flow closed (exactly one configuration is
     * auto-selected and never asked).
     */
    func requestCredentialSelection(params: CredentialSelectionParams) async throws  -> CredentialSelectionResult
    
    /**
     * Reports progress on a flow.
     */
    func progress(flowId: String, step: String, detail: String?) 
    
}

